#[test]
fn token_accepted_only_unexpired_with_prefix() {
    let mut r = Rng(17);
    let mut hits = 0;
    for _ in 0..N {
        let (cfg, _, cr, _, req) = case(&mut r);
        let Some(store) = &cfg.tokens else { continue };
        let t = *pick(&mut r, TOKS);
        let (_, res) = verify_token(store, &cr, t, req.now, req.mono);
        let Ok((u, ro)) = res else { continue };
        hits += 1;
        assert!(t.starts_with(b"nra_"));
        let cached = store.cache.iter().any(|c| c.user == u && c.role == ro && req.now <= c.expires_at);
        let filed = store.files.iter().any(|f| f.info.as_ref().is_some_and(|i| i.user == u && i.role == ro && req.now <= i.expires_at));
        assert!(cached || filed);
    }
    assert!(hits >= MIN_HITS);
}

#[test]
fn revoke_all_effective() {
    use nora_kernel::tokens::revoke_all_for_user;
    let mut r = Rng(22);
    let mut hits = 0;
    for _ in 0..N {
        let (cfg, _, cr, _, req) = case(&mut r);
        let Some(store) = &cfg.tokens else { continue };
        let user: &[u8] = pick(&mut r, &[b"u".as_slice(), b"c".as_slice()]);
        let (after, n) = revoke_all_for_user(store, user);
        if n == 0 { continue }
        for t in TOKS {
            if let (_, Ok((u, _))) = verify_token(&after, &cr, t, req.now, req.mono) {
                hits += 1;
                assert_ne!(u, user);
            }
        }
    }
    assert!(hits >= MIN_HITS, "{hits}");
}

#[test]
fn revoke_agrees() {
    use nora_kernel::tokens::{revoke_all_for_user, revoke_token, TokenError as KErr};
    let pool = pool();
    let mut r = Rng(0xDEC0DE);
    let (mut ok, mut all) = (0, 0);
    for i in 0..3000 {
        let c = case(&mut r, &pool);
        let (Some(store), Some(kstore)) = (&c.state.tokens, &c.kcfg.tokens) else { continue };
        let s = |x: &Vec<u8>| String::from_utf8(x.clone()).unwrap();
        let kc = |st: &KStore| { let mut v: Vec<_> = st.cache.iter().map(|x| (s(&x.key), s(&x.user))).collect(); v.sort(); v };
        let after = if r.chance(60) {
            let prefix = match r.below(4) {
                0 => "../../etc/passwd".to_string(),
                1 => "ABCDEF0123456789".to_string(),
                _ => match kstore.files.get(r.below(kstore.files.len().max(1) as u64) as usize) {
                    Some(f) => s(&f.prefix),
                    None => up::tokens::seam_sha256_hex(pick(&mut r, TOKENS))[..16].to_string(),
                },
            };
            let want = store.revoke_token(&prefix).map_err(|e| match e {
                up::tokens::TokenError::NotFound => KErr::NotFound,
                e => panic!("{e:?}"),
            });
            let (after, got) = revoke_token(kstore, prefix.as_bytes());
            assert_eq!(got, want, "case {i} revoke {prefix}");
            ok += got.is_ok() as usize;
            after
        } else {
            let user = pick(&mut r, &["ci", "dev", "ops", "cached", "nobody"]).to_string();
            let want = store.revoke_all_for_user(&user);
            let (after, got) = revoke_all_for_user(kstore, user.as_bytes());
            assert_eq!(got, want, "case {i} revoke all {user}");
            all += (got > 0) as usize;
            after
        };
        assert_eq!(files_on_disk(c.dir.path()), kfiles(&after), "case {i} files");
        let uc: Vec<(String, String)> = store.cache_entries().into_iter().map(|(k, u, _, _)| (k, u)).collect();
        assert_eq!(uc, kc(&after), "case {i} cache");
    }
    assert!(ok > 100 && all > 100, "{ok} {all}");
}

#[test]
fn revoked_token_rejected() {
    use nora_kernel::tokens::revoke_token;
    let mut r = Rng(21);
    let mut hits = 0;
    for _ in 0..N {
        let (cfg, _, cr, _, req) = case(&mut r);
        let Some(store) = &cfg.tokens else { continue };
        let t = *pick(&mut r, TOKS);
        let sha = cr.sha256_hex(t);
        let (after, res) = revoke_token(store, &sha[..16]);
        if res.is_err() { continue }
        hits += 1;
        let (_, v) = verify_token(&after, &cr, t, req.now, req.mono);
        assert!(v.is_err());
    }
    assert!(hits >= MIN_HITS, "{hits}");
}
